import React from "react";

export default function Heatmap({ data }) {
  const months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
  ];

  const entries = Object.entries(data).sort();
  const maxValue = Math.max(...Object.values(data).map(v => v || 0), 1);

  return (
    <div style={styles.container}>
      <div style={styles.grid}>
        {entries.map(([key, value]) => {
          const [year, month] = key.split("-");
          const monthNum = parseInt(month);
          const level = Math.ceil((value / maxValue) * 4);
          const monthName = months[monthNum - 1];

          return (
            <div key={key} style={styles.item}>
              <div style={{
                ...styles.box,
                ...getHeatStyle(level)
              }}>
                <span style={styles.tooltip}>{monthName} {year}: {value}</span>
              </div>
              <div style={styles.label}>{monthName}</div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function getHeatStyle(level) {
  const styles = {
    0: { background: "rgba(203, 213, 225, 0.1)" },
    1: { background: "rgba(34, 197, 94, 0.3)" },
    2: { background: "rgba(34, 197, 94, 0.5)" },
    3: { background: "rgba(34, 197, 94, 0.7)" },
    4: { background: "rgba(34, 197, 94, 1)" }
  };
  return styles[level] || styles[0];
}

const styles = {
  container: {
    marginTop: 16,
    width: "100%",
  },
  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(60px, 1fr))",
    gap: 8,
  },
  item: {
    textAlign: "center",
  },
  box: {
    aspectRatio: "1",
    borderRadius: 8,
    cursor: "pointer",
    position: "relative",
    transition: "transform 0.2s, box-shadow 0.2s",
    border: "1px solid rgba(255,255,255,0.1)",
  },
  label: {
    fontSize: 11,
    marginTop: 4,
    opacity: 0.8,
  },
  tooltip: {
    visibility: "hidden",
    position: "absolute",
    zIndex: 100,
    background: "rgba(0, 0, 0, 0.9)",
    color: "white",
    textAlign: "center",
    padding: "6px 8px",
    borderRadius: 4,
    bottom: "125%",
    left: "50%",
    white_space: "nowrap",
    transform: "translateX(-50%)",
    fontSize: 12,
  },
};
